CREATE TABLE clients (client_id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL);
CREATE TABLE search_criteria (criterion_id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients, query TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)));
CREATE TABLE runs (run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, source TEXT NOT NULL, source_version TEXT, coverage TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE run_queries (query_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs, client_id TEXT REFERENCES clients, country TEXT NOT NULL, query TEXT NOT NULL, original_url TEXT, effective_url TEXT, UNIQUE(run_id, country, query));
CREATE TABLE advertisers (source TEXT NOT NULL, advertiser_id TEXT NOT NULL, PRIMARY KEY(source, advertiser_id));
CREATE TABLE ads (source TEXT NOT NULL, ad_id TEXT NOT NULL, advertiser_id TEXT, first_observed_at TEXT NOT NULL, last_observed_at TEXT NOT NULL, payload_observed_at TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(source, ad_id), FOREIGN KEY(source, advertiser_id) REFERENCES advertisers(source, advertiser_id));
CREATE TABLE ad_observations (run_id TEXT NOT NULL REFERENCES runs, source TEXT NOT NULL, ad_id TEXT NOT NULL, observed_at TEXT NOT NULL, PRIMARY KEY(run_id,source,ad_id), FOREIGN KEY(source,ad_id) REFERENCES ads(source,ad_id));
CREATE TABLE observation_queries (run_id TEXT NOT NULL, source TEXT NOT NULL, ad_id TEXT NOT NULL, query_id TEXT NOT NULL REFERENCES run_queries, PRIMARY KEY(run_id,source,ad_id,query_id), FOREIGN KEY(run_id,source,ad_id) REFERENCES ad_observations(run_id,source,ad_id));
CREATE TABLE ad_urls (source TEXT NOT NULL, ad_id TEXT NOT NULL, url_original TEXT NOT NULL, url_normalized TEXT NOT NULL, kind TEXT NOT NULL, PRIMARY KEY(source,ad_id,url_original,kind), FOREIGN KEY(source,ad_id) REFERENCES ads(source,ad_id));
CREATE TABLE review_cases (case_id TEXT PRIMARY KEY, source TEXT NOT NULL, ad_id TEXT NOT NULL, reviewer TEXT NOT NULL, decision TEXT, status TEXT NOT NULL, FOREIGN KEY(source,ad_id) REFERENCES ads(source,ad_id));
CREATE TABLE advertiser_lists (entry_id TEXT PRIMARY KEY, source TEXT NOT NULL, advertiser_id TEXT NOT NULL, list_type TEXT NOT NULL CHECK(list_type IN ('white','black')), scope TEXT NOT NULL, reason TEXT NOT NULL, reviewer TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), case_id TEXT REFERENCES review_cases, FOREIGN KEY(source,advertiser_id) REFERENCES advertisers(source,advertiser_id), CHECK(list_type != 'black' OR case_id IS NOT NULL));
CREATE UNIQUE INDEX one_active_advertiser_list ON advertiser_lists(source,advertiser_id,scope) WHERE active=1;
CREATE TABLE brownlist (entry_id TEXT PRIMARY KEY, source TEXT NOT NULL, ad_id TEXT NOT NULL, scope TEXT NOT NULL, reason TEXT NOT NULL, reviewer TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), FOREIGN KEY(source,ad_id) REFERENCES ads(source,ad_id));
CREATE UNIQUE INDEX one_active_brown_entry ON brownlist(source,ad_id,scope) WHERE active=1;
CREATE TABLE report_events (report_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES review_cases, reported_at TEXT NOT NULL, reviewer TEXT NOT NULL, reference TEXT, status TEXT NOT NULL);
CREATE TABLE evidence (evidence_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES review_cases, type TEXT NOT NULL, hash TEXT, local_path TEXT, original_url TEXT);
CREATE TABLE audit_log (event_id TEXT PRIMARY KEY, actor TEXT NOT NULL, timestamp TEXT NOT NULL, operation TEXT NOT NULL, entity TEXT NOT NULL, before_json TEXT, after_json TEXT, reason TEXT NOT NULL);
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
CREATE INDEX ads_advertiser ON ads(source,advertiser_id);
CREATE INDEX observations_date ON ad_observations(observed_at);
CREATE INDEX cases_status ON review_cases(status);
CREATE INDEX queries_text ON run_queries(query);
